<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Create\TemplateCreateUsecase;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateUidVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateCodeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateThemeVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Create\TemplateCreateParams;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Create\TemplateCreateResult;

class TemplateCreateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly TemplateCreateUsecase $createUsecase,
    ) {
    }
    #[OA\Post(
        path: "/api/document/template",
        tags: ["Template"],
        description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateApiDTO")),
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateApiDTO")),
              new OA\Response(response: 422, description: "Constraint error"),
          ]
    )]
    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Create Template");
        $span = $this->startSpan("Create Template");
        $this->sql->begin();
        try {
            $value = $this->readTemplate($request);
            $result = $this->createUsecase->create($value);
            $this->sql->commit();
            $value = $this->mapTemplate($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readTemplate(ServerRequestInterface $request): TemplateCreateParams
    {
        $this->logDebug("Read entity for Template");
        $span = $this->startSpan("Read entity for Template");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new TemplateCreateParams();
            $valueUid = TemplateUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            $valueCode = TemplateCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            if (in_array('tenant', array_keys($body))) {
                $value->tenant(TemplateTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList));
            }
            if (in_array('theme', array_keys($body))) {
                $value->theme(TemplateThemeVO::tryFrom(isset($body['theme']['$ref']) ? new ThemeRef($body['theme']['$ref']) : null, $errorsList));
            }
            $valueChannel = TemplateChannelVO::tryFrom(isset($body['channel']) ? strtoupper($body['channel']) : null, $errorsList);
            if (null !== $valueChannel) {
                $value->channel($valueChannel);
            }
            $value->version(TemplateVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapTemplate(ServerRequestInterface $request, TemplateCreateResult $value): TemplateApiDTO
    {
        $this->logDebug("Map entity to output dto for Template");
        $span = $this->startSpan("Map entity to output dto for Template");
        try {
            $tenant = $value->getTenant();
            $theme = $value->getTheme();
            $dto = new TemplateApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->theme = $theme ? ['$ref' => $theme->uid()] : null;
            $dto->channel = $value->getChannel();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
